Since $\Dw$ and $\Zw$ are subrings of the complex numbers, they
inherit the usual notion of complex conjugation. We note that
$\omega\da = -\omega^3$. This yields the following formula:
\begin{equation}\label{eqn-adjoint}
  (a\omega^3+b\omega^2+c\omega+d)\da = -c\omega^3-b\omega^2-a\omega+d.
\end{equation}
Similarly, the sets $\Dw$ and $\Zw$ inherit the usual norm from the complex
numbers. It is given by the following explicit formula, for
$t=a\omega^3+b\omega^2+c\omega+d$:
\begin{equation}\label{eqn-cplx-norm}
  \snorm{t}^2 = t\da t = (a^2+b^2+c^2+d^2) + (cd+bc+ab-da) \sqrt{2}.
\end{equation}

For $t\in\Dw$ or $t\in\Zw$, the {\em weight} of $t$ is denoted 
$\sweight{t}$, and is given by:
\begin{equation}\label{eqn-weight}
  \sweight{t}^2 = a^2+b^2+c^2+d^2.
\end{equation}

\label{lem-ring-norm}
  Consider a vector $u\in\Dw^n$. If $\norm{u}^2$ is an integer, then
  $\weight{u}^2=\norm{u}^2$.

\label{lem-reducible}
  For a residue $x$, the following are equivalent:
  \begin{enumerate}\alphalabels
  \item $x$ is reducible;
  \item $x\in\s{0000,0101,1010,1111}$;
  \item $\sqrt{2}\,x = 0000$;
  \item $x\da x=0000$.
  \end{enumerate}
  Moreover, $x$ is twice reducible iff $x=0000$.

